const input = $input.first()?.json || {};
const execution = input.execution || {};
const workflow = input.workflow || {};
const error = execution.error || {};

const wfName = workflow.name || 'Unknown Workflow';
const wfId = workflow.id || 'N/A';
const failedNode = execution.lastNodeExecuted || error.node?.name || 'Unknown Node';
const errorMsg = error.message || error.description || 'Không có chi tiết lỗi';
const execId = execution.id || 'N/A';
const now = new Date();
const timeStr = now.toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' });

const alertText = [
  `🚨 **[DEAD-LETTER ALERT: N8N WORKFLOW GẶP LỖI]**`,
  `- **Workflow:** \`${wfName}\` (ID: \`${wfId}\`)`,
  `- **Node gặp lỗi:** \`${failedNode}\``,
  `- **Nguyên nhân:** ${errorMsg}`,
  `- **Execution ID:** \`${execId}\``,
  `- **Thời gian:** \`${timeStr}\``,
  `\n> ⚠️ *Vui lòng kiểm tra lại cấu hình kết nối, hạn mức API hoặc logs n8n để khắc phục.*`
].join('\n');

return [{
  json: {
    workflowName: wfName,
    workflowId: wfId,
    failedNode,
    errorMessage: errorMsg,
    executionId: execId,
    timestamp: now.toISOString(),
    reportText: alertText
  }
}];
